int flaeche(int breite, int hoehe) {
    return breite * hoehe;
}

int umfang(int breite, int hoehe) {
    return 2 * (breite + hoehe);
}

int main() {
    std::cout << "Fläche: " << flaeche(3, 4) << "\n";
